"""Generate guarded native item driver adapter; transport implementation remains hand-written."""
import ast
from pathlib import Path
root=Path(__file__).resolve().parents[1]
tree=ast.parse((root/'tools/generate-layer-families.py').read_text(encoding='utf-8'))
guard=next(ast.literal_eval(n.value) for n in tree.body if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='guard' for t in n.targets))
text='''package fpv.construction;
// Generated by tools/generate-layer-massdrivers.py.
import arc.math.geom.Geometry;
import mindustry.gen.*;
import mindustry.game.Team;
import mindustry.world.*;
import mindustry.world.blocks.distribution.MassDriver;

final class LayerMassDriverFamilies {
    static boolean supports(Class<?> type){return type==MassDriver.MassDriverBuild.class;}
    static Building create(LayerBuildingAdapter owner,Block block,Class<?> type){return new UpperMassDriver((MassDriver)block,owner);}
    static boolean configure(LayerBuildingAdapter owner,Building building,Object value){return LayerMassDriverBehavior.configure(owner,building,value);}
    static final class UpperMassDriver extends MassDriver.MassDriverBuild {
        final LayerBuildingAdapter owner;
        final LayerMassDriverBehavior.Pod pod=new LayerMassDriverBehavior.Pod();
        UpperMassDriver(MassDriver block,LayerBuildingAdapter owner){block.super();this.owner=owner;}
'''
text+='\n'.join('        '+line for line in guard.strip().splitlines())
text+='''
        @Override public void updateTile(){LayerMassDriverBehavior.update(owner,this);}
        @Override protected boolean linkValid(){return LayerMassDriverBehavior.link(owner,this)!=null;}
        @Override protected boolean shooterValid(Building other){return LayerMassDriverBehavior.shooter(owner,this,other);}
        @Override public void onRemoved(){}
        @Override public void write(arc.util.io.Writes out){super.write(out);pod.write(out);}
        @Override public void read(arc.util.io.Reads in,byte version){super.read(in,version);pod.read(in,block.itemCapacity);}
    }
}
'''
(root/'src/main/java/fpv/construction/LayerMassDriverFamilies.java').write_text(text,encoding='utf-8')
print('Generated guarded item mass driver')
